import { createElement } from '../../vendor/react.js';

export function Button({
  variant = 'secondary',
  disabled = false,
  children = '',
} = {}) {
  const kind = variant === 'primary' ? 'primary' : 'secondary';
  return createElement(
    'button',
    {
      type: 'button',
      className: `btn btn-${kind}`,
      disabled: Boolean(disabled),
    },
    children,
  );
}

import { createElement } from '../../vendor/react.js';

export function Toolbar() {
  return createElement(
    'nav',
    { className: 'toolbar' },
    createElement('span', { className: 'doc-title' }, 'Untitled'),
    createElement('button', { type: 'button', className: 'ghost' }, 'Cancel'),
  );
}

import { createElement } from '../../vendor/react.js';
import { Button } from '../ui/Button.js';

export function LoginForm() {
  return createElement(
    'form',
    { className: 'login' },
    createElement('label', { htmlFor: 'email' }, 'Email'),
    createElement('input', { id: 'email', name: 'email', type: 'email' }),
    createElement(Button, { variant: 'primary', children: 'Sign in' }),
  );
}

